    bird: 'passaro pet bird', rabbit: 'coelho pet rabbit', turtle: 'tartaruga pet turtle', 'paw-print': 'pet animal veterinario petshop vet', bone: 'osso pet racao dog food', church: 'igreja dizimo religiao church tithe',
    flower: 'flor floricultura flower', trees: 'jardim arvores jardinagem garden trees', sprout: 'planta muda plant', leaf: 'natureza sustentavel nature eco', sun: 'sol verao sun summer',
