  function restoreSnap() { if (!S.snap) return; const o = JSON.parse(S.snap); S.partes = o.p; S.itens = o.i; S.nota = o.n; S.notaDirty = o.nd; S.partesDirty = o.pd; S.sel = 0; S.msg = ''; }
