      if (k === 'total') { if (S.inline) { render(); if (S.totalV > 0) salvarReduzido(); } else if (S.pd) S.dirty = true; else render(); }
      // não fecha o pop aqui: fechar no blur é frágil (dispara em blur/foco transitório de automação/alguns
