  const valor = (r, dark) => '<b style="text-align:right;font-size:19px;font-weight:800;letter-spacing:-.03em;white-space:nowrap;color:' + (r.dir === 'entrada' ? (dark ? GR : '#1E6B0C') : (dark ? RD : '#B3261E')) + '">' + (r.dir === 'entrada' ? '+ ' : '– ') + 'R$ ' + brl(r.amt) + '</b>';
