    try { const t = await lerTexto(file); raw = /<STMTTRN>/i.test(t) ? parseOfx(t) : parseCsv(t); } catch (e) { raw = []; }
    if (!raw.length) return alerta('Não achei lançamentos nesse arquivo. Use o extrato em OFX ou CSV exportado pelo banco.');
