    const h0 = c.getBoundingClientRect().height, h1 = c.querySelector('[data-head]').offsetHeight + 22;
    c.style.transition = 'none'; c.style.height = h0 + 'px'; c.style.overflow = 'hidden'; void c.offsetHeight;
